package com.tamzode.tracker;

import java.sql.Date;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

@RestController @RequestMapping("/api")
public class TrackerController {
 private final JdbcTemplate db;
 public TrackerController(JdbcTemplate db){this.db=db;}
 @GetMapping("/health") Map<String,String> health(){return Map.of("status","ok");}
 private static final String PROJECT_SELECT="SELECT p.id,p.name,p.description,p.category,p.technology,p.status,p.priority,p.start_date AS \"startDate\",p.deadline,p.owner,p.notes,p.useful_links AS \"usefulLinks\",p.repository_url AS \"repositoryUrl\",p.progress_mode AS \"progressMode\",p.current_stage AS \"currentStage\",p.created_at AS \"createdAt\",p.updated_at AS \"updatedAt\",count(t.id) FILTER(WHERE t.status<>'Cancelled' AND NOT EXISTS (SELECT 1 FROM tasks child WHERE child.parent_task_id=t.id))::int AS \"taskCount\",(SELECT count(*)::int FROM milestones m WHERE m.project_id=p.id) AS \"milestoneCount\",count(t.id) FILTER(WHERE t.status='Done' AND NOT EXISTS (SELECT 1 FROM tasks child WHERE child.parent_task_id=t.id))::int AS \"completedTasks\",CASE WHEN count(t.id) FILTER(WHERE t.status<>'Cancelled' AND NOT EXISTS (SELECT 1 FROM tasks child WHERE child.parent_task_id=t.id))=0 THEN 0 ELSE round(100.0*count(t.id) FILTER(WHERE t.status='Done' AND NOT EXISTS (SELECT 1 FROM tasks child WHERE child.parent_task_id=t.id))/count(t.id) FILTER(WHERE t.status<>'Cancelled' AND NOT EXISTS (SELECT 1 FROM tasks child WHERE child.parent_task_id=t.id)))::int END AS progress FROM projects p LEFT JOIN tasks t ON t.project_id=p.id";
 @GetMapping("/dashboard") Map<String,Object> dashboard(){return db.queryForMap("SELECT (SELECT count(*) FROM projects WHERE status<>'Archived')::int AS total,(SELECT count(*) FROM projects WHERE status='In Progress')::int AS active,(SELECT count(*) FROM tasks t WHERE t.status='Done' AND NOT EXISTS (SELECT 1 FROM tasks child WHERE child.parent_task_id=t.id))::int AS completed,(SELECT count(*) FROM tasks t WHERE t.status IN ('To Do','In Review') AND NOT EXISTS (SELECT 1 FROM tasks child WHERE child.parent_task_id=t.id))::int AS pending,(SELECT count(*) FROM tasks t WHERE t.status='In Progress' AND NOT EXISTS (SELECT 1 FROM tasks child WHERE child.parent_task_id=t.id))::int AS inProgress,(SELECT count(*) FROM tasks t WHERE t.status='Blocked' AND NOT EXISTS (SELECT 1 FROM tasks child WHERE child.parent_task_id=t.id))::int AS blocked,(SELECT count(*) FROM tasks WHERE status NOT IN ('Done','Cancelled') AND due_date>=CURRENT_DATE AND due_date<CURRENT_DATE+7)::int AS upcoming,(SELECT count(*) FROM tasks WHERE status NOT IN ('Done','Cancelled') AND due_date<CURRENT_DATE)::int AS overdue,(SELECT count(*) FROM milestones WHERE status<>'Completed' AND target_date>=CURRENT_DATE AND target_date<CURRENT_DATE+7)::int AS upcomingMilestones,(SELECT coalesce(sum(duration_seconds),0)::bigint FROM time_entries)::bigint AS totalTimeSeconds");}
 private List<Map<String,Object>> projects(String where,Object...args){return db.queryForList(PROJECT_SELECT+" "+where+" GROUP BY p.id ORDER BY p.created_at DESC",args);}
 @GetMapping("/projects") List<Map<String,Object>> getProjects(@RequestParam(required=false) String status,@RequestParam(defaultValue="0") int offset,@RequestParam(defaultValue="100") int limit){var args=new java.util.ArrayList<Object>();String where="";if(status!=null){where="WHERE p.status=?";args.add(status);}return db.queryForList(PROJECT_SELECT+" "+where+" GROUP BY p.id ORDER BY p.created_at DESC LIMIT ? OFFSET ?",append(args,Math.max(1,Math.min(limit,200)),Math.max(0,offset)).toArray());}
 @GetMapping("/projects/{id}") Map<String,Object> getProject(@PathVariable long id){return project(id);}
 private Map<String,Object> project(long id){return projects("WHERE p.id=?",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Project not found"));}
 record ProjectInput(@NotBlank @Size(max=140) String name,String description,@Size(max=100) String category,@Size(max=300) String technology,String status,String priority,java.time.LocalDate startDate,java.time.LocalDate deadline,@Size(max=120) String owner,String notes,String usefulLinks,String repositoryUrl,String progressMode,String currentStage){}
 @PostMapping("/projects") @Transactional Map<String,Object> createProject(@Valid @RequestBody ProjectInput p){db.update("INSERT INTO projects(name,description,category,technology,status,priority,start_date,deadline,owner,notes,useful_links,repository_url,progress_mode,current_stage) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",p.name(),p.description(),p.category(),p.technology(),value(p.status(),"Planned",Set.of("Planned","In Progress","On Hold","Completed","Archived")),value(p.priority(),"Medium",Set.of("Low","Medium","High","Urgent","Critical")),p.startDate(),p.deadline(),p.owner(),p.notes(),p.usefulLinks(),p.repositoryUrl(),value(p.progressMode(),"tasks",Set.of("tasks","milestones")),value(p.currentStage(),"Planning",Set.of("Planning","Design","Development","Testing","Deployment","Completed")));long id=db.queryForObject("SELECT currval(pg_get_serial_sequence('projects','id'))",Long.class);log("created","project",id,p.name(),"Project created");return project(id);}
 @PutMapping("/projects/{id}") @Transactional Map<String,Object> updateProject(@PathVariable long id,@Valid @RequestBody ProjectInput p){Map<String,Object> before=project(id);String stage=value(p.currentStage(),"Planning",Set.of("Planning","Design","Development","Testing","Deployment","Completed"));db.update("UPDATE projects SET name=?,description=?,category=?,technology=?,status=?,priority=?,start_date=?,deadline=?,owner=?,notes=?,useful_links=?,repository_url=?,progress_mode=?,current_stage=?,updated_at=now() WHERE id=?",p.name(),p.description(),p.category(),p.technology(),value(p.status(),"Planned",Set.of("Planned","In Progress","On Hold","Completed","Archived")),value(p.priority(),"Medium",Set.of("Low","Medium","High","Urgent","Critical")),p.startDate(),p.deadline(),p.owner(),p.notes(),p.usefulLinks(),p.repositoryUrl(),value(p.progressMode(),"tasks",Set.of("tasks","milestones")),stage,id);if(!stage.equals(before.get("currentStage")))log("stage changed","project",id,p.name(),"Stage: "+before.get("currentStage")+" → "+stage);else log("updated","project",id,p.name(),"Project details updated");return project(id);}
 @DeleteMapping("/projects/{id}") @Transactional Map<String,String> deleteProject(@PathVariable long id){Map<String,Object> p=project(id);db.update("DELETE FROM projects WHERE id=?",id);log("deleted","project",id,(String)p.get("name"),"Project and related records deleted");return Map.of("message","Project deleted");}

 private static final String TASK_SELECT="SELECT t.id,t.title,t.description,t.project_id AS \"projectId\",p.name AS \"projectName\",t.project_phase_id AS \"projectPhaseId\",t.milestone_id AS \"milestoneId\",m.name AS \"milestoneName\",t.parent_task_id AS \"parentTaskId\",t.status,t.priority,t.start_date AS \"startDate\",t.due_date AS \"dueDate\",t.estimated_minutes AS \"estimatedMinutes\",coalesce((SELECT sum(e.duration_seconds) FROM time_entries e WHERE e.task_id=t.id),0)::bigint AS \"actualSeconds\",NOT EXISTS(SELECT 1 FROM task_dependencies d JOIN tasks dep ON dep.id=d.depends_on_task_id WHERE d.task_id=t.id AND dep.status<>'Done') AS \"dependencyReady\",(SELECT count(*)::int FROM task_dependencies d WHERE d.task_id=t.id) AS \"dependencyCount\",t.completed_at AS \"completedAt\",t.assignee,t.tags,t.notes,t.created_at AS \"createdAt\",t.updated_at AS \"updatedAt\" FROM tasks t JOIN projects p ON p.id=t.project_id LEFT JOIN milestones m ON m.id=t.milestone_id";
 @GetMapping("/tasks") List<Map<String,Object>> getTasks(@RequestParam(required=false) Long projectId,@RequestParam(required=false) String status,@RequestParam(required=false) String q,@RequestParam(required=false) String priority,@RequestParam(required=false) Long milestoneId,@RequestParam(required=false) java.time.LocalDate dueFrom,@RequestParam(required=false) java.time.LocalDate dueTo,@RequestParam(defaultValue="due") String sort,@RequestParam(defaultValue="0") int offset,@RequestParam(defaultValue="200") int limit){var args=new java.util.ArrayList<Object>();var filters=new java.util.ArrayList<String>();if(projectId!=null){filters.add("t.project_id=?");args.add(projectId);}if(status!=null){filters.add("t.status=?");args.add(value(status,null,Set.of("To Do","In Progress","In Review","Done","Blocked","Cancelled")));}if(priority!=null){filters.add("t.priority=?");args.add(value(priority,null,Set.of("Low","Medium","High","Urgent","Critical")));}if(milestoneId!=null){filters.add("t.milestone_id=?");args.add(milestoneId);}if(q!=null&&!q.isBlank()){filters.add("(t.title ILIKE ? OR coalesce(t.description,'') ILIKE ?)");args.add("%"+q.trim()+"%");args.add("%"+q.trim()+"%");}if(dueFrom!=null&&dueTo!=null&&dueTo.isBefore(dueFrom))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Due date end must be on or after start");if(dueFrom!=null){filters.add("t.due_date>=?");args.add(dueFrom);}if(dueTo!=null){filters.add("t.due_date<=?");args.add(dueTo);}String order=switch(sort){case "priority"->"CASE t.priority WHEN 'Critical' THEN 1 WHEN 'Urgent' THEN 2 WHEN 'High' THEN 3 WHEN 'Medium' THEN 4 ELSE 5 END,t.due_date NULLS LAST";case "created"->"t.created_at DESC";case "title"->"lower(t.title)";case "due"->"t.due_date NULLS LAST,t.created_at DESC";default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid task sort order");};String where=filters.isEmpty()?"":" WHERE "+String.join(" AND ",filters);args.add(Math.max(1,Math.min(limit,500)));args.add(Math.max(0,offset));return db.queryForList(TASK_SELECT+where+" ORDER BY "+order+" LIMIT ? OFFSET ?",args.toArray());}
 record TaskInput(@NotBlank @Size(max=180) String title,String description,@NotNull Long projectId,String status,String priority,java.time.LocalDate dueDate,@Size(max=120) String assignee,List<String> tags,String notes,Long parentTaskId,java.time.LocalDate startDate,Integer estimatedMinutes,Long projectPhaseId,Long milestoneId){}
 @PostMapping("/tasks") @Transactional Map<String,Object> createTask(@Valid @RequestBody TaskInput t){ensureProject(t.projectId());ensureParent(t.parentTaskId(),t.projectId(),null);ensurePhase(t.projectPhaseId(),t.projectId());ensureMilestone(t.milestoneId(),t.projectId());String status=value(t.status(),"To Do",Set.of("To Do","In Progress","In Review","Done","Blocked","Cancelled"));db.update("INSERT INTO tasks(title,description,project_id,project_phase_id,milestone_id,parent_task_id,status,priority,start_date,due_date,estimated_minutes,completed_at,assignee,tags,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,CASE WHEN ?='Done' THEN now() ELSE NULL END,?,?,?)",t.title(),t.description(),t.projectId(),t.projectPhaseId(),t.milestoneId(),t.parentTaskId(),status,value(t.priority(),"Medium",Set.of("Low","Medium","High","Urgent","Critical")),t.startDate(),t.dueDate(),t.estimatedMinutes(),status,t.assignee(),t.tags()==null?new String[]{}:t.tags().toArray(String[]::new),t.notes());long id=db.queryForObject("SELECT currval(pg_get_serial_sequence('tasks','id'))",Long.class);log("created","task",id,t.title(),"Task created");return task(id);}
 @PutMapping("/tasks/{id}") @Transactional Map<String,Object> updateTask(@PathVariable long id,@Valid @RequestBody TaskInput t){Map<String,Object> before=task(id);ensureProject(t.projectId());ensureParent(t.parentTaskId(),t.projectId(),id);ensurePhase(t.projectPhaseId(),t.projectId());ensureMilestone(t.milestoneId(),t.projectId());String status=value(t.status(),"To Do",Set.of("To Do","In Progress","In Review","Done","Blocked","Cancelled"));db.update("UPDATE tasks SET title=?,description=?,project_id=?,project_phase_id=?,milestone_id=?,parent_task_id=?,status=?,priority=?,start_date=?,due_date=?,estimated_minutes=?,completed_at=CASE WHEN ?='Done' THEN coalesce(completed_at,now()) ELSE NULL END,assignee=?,tags=?,notes=?,updated_at=now() WHERE id=?",t.title(),t.description(),t.projectId(),t.projectPhaseId(),t.milestoneId(),t.parentTaskId(),status,value(t.priority(),"Medium",Set.of("Low","Medium","High","Urgent","Critical")),t.startDate(),t.dueDate(),t.estimatedMinutes(),status,t.assignee(),t.tags()==null?new String[]{}:t.tags().toArray(String[]::new),t.notes(),id);if(!java.util.Objects.equals(before.get("status"),status))log(status.equals("Done")?"completed":"status changed","task",id,t.title(),"Status: "+before.get("status")+" → "+status);if(!java.util.Objects.equals(before.get("priority"),t.priority()))log("priority changed","task",id,t.title(),"Priority: "+before.get("priority")+" → "+t.priority());if(!java.util.Objects.equals(before.get("dueDate"),t.dueDate()))log("deadline changed","task",id,t.title(),"Due date updated");if(java.util.Objects.equals(before.get("status"),status)&&java.util.Objects.equals(before.get("priority"),t.priority())&&java.util.Objects.equals(before.get("dueDate"),t.dueDate()))log("updated","task",id,t.title(),"Task details updated");return task(id);}
 @PatchMapping("/tasks/{id}/status") @Transactional Map<String,Object> taskStatus(@PathVariable long id,@RequestBody Map<String,String> body){Map<String,Object> before=task(id);String s=value(body.get("status"),null,Set.of("To Do","In Progress","In Review","Done","Blocked","Cancelled"));db.update("UPDATE tasks SET status=?,completed_at=CASE WHEN ?='Done' THEN coalesce(completed_at,now()) ELSE NULL END,updated_at=now() WHERE id=?",s,s,id);if(!s.equals(before.get("status")))log(s.equals("Done")?"completed":"status changed","task",id,(String)before.get("title"),"Status: "+before.get("status")+" → "+s);return task(id);}
 record BulkTaskInput(@jakarta.validation.constraints.NotEmpty @jakarta.validation.constraints.Size(max=100) List<Long> ids,String status,String priority){}
 @PatchMapping("/tasks/bulk") @Transactional Map<String,Object> bulkTasks(@Valid @RequestBody BulkTaskInput input){if(input.status()==null&&input.priority()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a status or priority change");String status=input.status()==null?null:value(input.status(),null,Set.of("To Do","In Progress","In Review","Done","Blocked","Cancelled"));String priority=input.priority()==null?null:value(input.priority(),null,Set.of("Low","Medium","High","Urgent","Critical"));var unique=new java.util.LinkedHashSet<>(input.ids());if(unique.size()!=input.ids().size())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Remove duplicate task IDs");var before=unique.stream().map(this::task).toList();for(Map<String,Object> t:before){long id=((Number)t.get("id")).longValue();if(status!=null)db.update("UPDATE tasks SET status=?,completed_at=CASE WHEN ?='Done' THEN coalesce(completed_at,now()) ELSE NULL END,updated_at=now() WHERE id=?",status,status,id);if(priority!=null)db.update("UPDATE tasks SET priority=?,updated_at=now() WHERE id=?",priority,id);if(status!=null&&!status.equals(t.get("status")))log(status.equals("Done")?"completed":"status changed","task",id,(String)t.get("title"),"Status: "+t.get("status")+" → "+status);if(priority!=null&&!priority.equals(t.get("priority")))log("priority changed","task",id,(String)t.get("title"),"Priority: "+t.get("priority")+" → "+priority);}return Map.of("updated",before.size());}
 @DeleteMapping("/tasks/{id}") Map<String,String> deleteTask(@PathVariable long id){Map<String,Object> t=task(id);db.update("DELETE FROM tasks WHERE id=?",id);log("deleted","task",id,(String)t.get("title"),"Task deleted");return Map.of("message","Task deleted");}
 private Map<String,Object> task(long id){return db.queryForList(TASK_SELECT+" WHERE t.id=?",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Task not found"));}
 @GetMapping("/tasks/{id}/details") Map<String,Object> taskDetails(@PathVariable long id){Map<String,Object> t=task(id);t.put("subtasks",db.queryForList(TASK_SELECT+" WHERE t.parent_task_id=? ORDER BY t.created_at",id));t.put("dependencies",db.queryForList("SELECT dep.id,dep.title,dep.status FROM task_dependencies d JOIN tasks dep ON dep.id=d.depends_on_task_id WHERE d.task_id=? ORDER BY dep.title",id));t.put("timeEntries",db.queryForList("SELECT id,started_at AS \"startedAt\",ended_at AS \"endedAt\",duration_seconds AS \"durationSeconds\",notes FROM time_entries WHERE task_id=? ORDER BY started_at DESC LIMIT 100",id));t.put("activity",db.queryForList("SELECT id,action,details,created_at AS \"createdAt\" FROM activity WHERE entity_type='task' AND entity_id=? ORDER BY created_at DESC LIMIT 50",id));return t;}
 record DependencyInput(@jakarta.validation.constraints.NotNull List<Long> ids){}
 @PutMapping("/tasks/{id}/dependencies") @Transactional Map<String,Object> setDependencies(@PathVariable long id,@Valid @RequestBody DependencyInput input){Map<String,Object> task=task(id);var unique=new java.util.LinkedHashSet<>(input.ids());if(unique.size()!=input.ids().size())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Remove duplicate dependencies");if(unique.size()>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A task can have at most 100 dependencies");for(Long dependencyId:unique){if(dependencyId==null||dependencyId==id)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A task cannot depend on itself");Map<String,Object> dependency=task(dependencyId);if(!task.get("projectId").equals(dependency.get("projectId")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Dependencies must belong to the same project");Integer cycle=db.queryForObject("WITH RECURSIVE chain(id) AS (SELECT ?::bigint UNION SELECT d.depends_on_task_id FROM task_dependencies d JOIN chain c ON d.task_id=c.id) SELECT count(*) FROM chain WHERE id=?",Integer.class,dependencyId,id);if(cycle!=null&&cycle>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"This dependency would create a cycle");}db.update("DELETE FROM task_dependencies WHERE task_id=?",id);for(Long dependencyId:unique)db.update("INSERT INTO task_dependencies(task_id,depends_on_task_id) VALUES(?,?)",id,dependencyId);log("updated","task",id,(String)task.get("title"),"Task dependencies updated");return Map.of("dependencies",db.queryForList("SELECT dep.id,dep.title,dep.status FROM task_dependencies d JOIN tasks dep ON dep.id=d.depends_on_task_id WHERE d.task_id=? ORDER BY dep.title",id));}
 @GetMapping("/tasks/analytics") Map<String,Object> taskAnalytics(@RequestParam(required=false) Long projectId,@RequestParam(required=false) java.time.LocalDate from,@RequestParam(required=false) java.time.LocalDate to){java.time.LocalDate end=to==null?java.time.LocalDate.now():to,start=from==null?end.minusDays(6):from;if(end.isBefore(start))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"End date must be on or after start date");if(java.time.temporal.ChronoUnit.DAYS.between(start,end)>365)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Date range cannot exceed 366 days");String projectClause=projectId==null?"":" AND project_id=?";Object[] projectArg=projectId==null?new Object[]{}:new Object[]{projectId};var summaryArgs=new java.util.ArrayList<Object>();summaryArgs.add(start);summaryArgs.add(end);summaryArgs.addAll(java.util.Arrays.asList(projectArg));Map<String,Object> summary=db.queryForMap("SELECT count(*) FILTER(WHERE status NOT IN ('Done','Cancelled'))::int AS active,count(*) FILTER(WHERE status NOT IN ('Done','Cancelled') AND due_date=CURRENT_DATE)::int AS \"dueToday\",count(*) FILTER(WHERE status NOT IN ('Done','Cancelled') AND due_date<CURRENT_DATE)::int AS overdue,count(*) FILTER(WHERE status='Done')::int AS \"completedAllTime\" FROM tasks WHERE NOT EXISTS (SELECT 1 FROM tasks child WHERE child.parent_task_id=tasks.id) AND (due_date IS NULL OR due_date BETWEEN ? AND ? OR status='Done')"+projectClause,summaryArgs.toArray());var chartArgs=new java.util.ArrayList<Object>();chartArgs.add(start);chartArgs.add(end);chartArgs.addAll(java.util.Arrays.asList(projectArg));List<Map<String,Object>> statuses=db.queryForList("SELECT status,count(*)::int AS count FROM tasks WHERE status<>'Cancelled' AND NOT EXISTS (SELECT 1 FROM tasks child WHERE child.parent_task_id=tasks.id) AND (due_date IS NULL OR due_date BETWEEN ? AND ?)"+projectClause+" GROUP BY status ORDER BY status",chartArgs.toArray());var priorityArgs=new java.util.ArrayList<Object>();priorityArgs.add(start);priorityArgs.add(end);priorityArgs.addAll(java.util.Arrays.asList(projectArg));List<Map<String,Object>> priorities=db.queryForList("SELECT priority,count(*)::int AS count FROM tasks WHERE status NOT IN ('Done','Cancelled') AND NOT EXISTS (SELECT 1 FROM tasks child WHERE child.parent_task_id=tasks.id) AND (due_date IS NULL OR due_date BETWEEN ? AND ?)"+projectClause+" GROUP BY priority ORDER BY CASE priority WHEN 'Critical' THEN 1 WHEN 'Urgent' THEN 2 WHEN 'High' THEN 3 WHEN 'Medium' THEN 4 ELSE 5 END",priorityArgs.toArray());var trendArgs=new java.util.ArrayList<Object>();trendArgs.add(start);trendArgs.add(end);trendArgs.addAll(java.util.Arrays.asList(projectArg));List<Map<String,Object>> weekly=db.queryForList("SELECT d.day::date AS \"date\",count(t.id)::int AS count FROM generate_series(?::date,?::date,interval '1 day') d(day) LEFT JOIN tasks t ON t.completed_at::date=d.day::date AND t.status='Done' AND NOT EXISTS (SELECT 1 FROM tasks child WHERE child.parent_task_id=t.id)"+(projectId==null?"":" AND t.project_id=?")+" GROUP BY d.day ORDER BY d.day",trendArgs.toArray());return Map.of("summary",summary,"status",statuses,"priority",priorities,"weeklyCompleted",weekly,"from",start,"to",end);}
 private void ensureProject(long id){if(db.queryForObject("SELECT count(*) FROM projects WHERE id=?",Integer.class,id)==0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose an existing project");}
 private void ensureParent(Long parentId,long projectId,Long taskId){if(parentId==null)return;if(parentId.equals(taskId))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A task cannot be its own parent");if(db.queryForObject("SELECT count(*) FROM tasks WHERE id=? AND project_id=?",Integer.class,parentId,projectId)==0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a parent task from the same project");}
 private void ensurePhase(Long phaseId,long projectId){if(phaseId!=null&&db.queryForObject("SELECT count(*) FROM project_phases WHERE id=? AND project_id=?",Integer.class,phaseId,projectId)==0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a phase from the same project");}
 private void ensureMilestone(Long milestoneId,long projectId){if(milestoneId!=null&&db.queryForObject("SELECT count(*) FROM milestones WHERE id=? AND project_id=?",Integer.class,milestoneId,projectId)==0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a milestone from the same project");}

 @GetMapping("/milestones") List<Map<String,Object>> milestones(@RequestParam(required=false) Long projectId){return projectId==null?db.queryForList("SELECT m.id,m.name,m.description,m.project_id AS \"projectId\",p.name AS \"projectName\",m.target_date AS \"targetDate\",m.status,m.created_at AS \"createdAt\" FROM milestones m JOIN projects p ON p.id=m.project_id ORDER BY m.target_date NULLS LAST"):db.queryForList("SELECT m.id,m.name,m.description,m.project_id AS \"projectId\",p.name AS \"projectName\",m.target_date AS \"targetDate\",m.status,m.created_at AS \"createdAt\" FROM milestones m JOIN projects p ON p.id=m.project_id WHERE m.project_id=? ORDER BY m.target_date NULLS LAST",projectId);}
 record MilestoneInput(@NotBlank @Size(max=160) String name,String description,@NotNull Long projectId,java.time.LocalDate targetDate,String status){}
 @PostMapping("/milestones") @Transactional Map<String,Object> addMilestone(@Valid @RequestBody MilestoneInput m){ensureProject(m.projectId());db.update("INSERT INTO milestones(name,description,project_id,target_date,status) VALUES(?,?,?,?,?)",m.name(),m.description(),m.projectId(),m.targetDate(),value(m.status(),"Planned",Set.of("Planned","In Progress","Completed")));long id=db.queryForObject("SELECT currval(pg_get_serial_sequence('milestones','id'))",Long.class);log("created","milestone",id,m.name(),"Milestone created");return db.queryForMap("SELECT id,name,description,project_id AS \"projectId\",target_date AS \"targetDate\",status FROM milestones WHERE id=?",id);}
 @PutMapping("/milestones/{id}") @Transactional Map<String,Object> updateMilestone(@PathVariable long id,@Valid @RequestBody MilestoneInput m){if(db.update("UPDATE milestones SET name=?,description=?,project_id=?,target_date=?,status=?,updated_at=now() WHERE id=?",m.name(),m.description(),m.projectId(),m.targetDate(),value(m.status(),"Planned",Set.of("Planned","In Progress","Completed")),id)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Milestone not found");log("updated","milestone",id,m.name(),"Milestone updated");return db.queryForMap("SELECT id,name,description,project_id AS \"projectId\",target_date AS \"targetDate\",status FROM milestones WHERE id=?",id);}
 @DeleteMapping("/milestones/{id}") Map<String,String> deleteMilestone(@PathVariable long id){if(db.update("DELETE FROM milestones WHERE id=?",id)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Milestone not found");return Map.of("message","Milestone deleted");}

 record UpdateInput(@NotBlank String workedOn,String completed,String blockers,String nextSteps){}
 @PostMapping("/daily-updates") @Transactional Map<String,Object> addDailyUpdate(@Valid @RequestBody UpdateInput u){db.update("INSERT INTO daily_updates(worked_on,completed,blockers,next_steps) VALUES(?,?,?,?)",u.workedOn(),u.completed(),u.blockers(),u.nextSteps());long id=db.queryForObject("SELECT currval(pg_get_serial_sequence('daily_updates','id'))",Long.class);log("logged","daily update",id,"Daily progress note",u.workedOn());return db.queryForMap("SELECT id,worked_on AS \"workedOn\",completed,blockers, next_steps AS \"nextSteps\",created_at AS \"createdAt\" FROM daily_updates WHERE id=?",id);}
 @GetMapping("/daily-updates") List<Map<String,Object>> updates(@RequestParam(defaultValue="0") int offset,@RequestParam(defaultValue="50") int limit){return db.queryForList("SELECT id,worked_on AS \"workedOn\",completed,blockers,next_steps AS \"nextSteps\",created_at AS \"createdAt\" FROM daily_updates ORDER BY created_at DESC LIMIT ? OFFSET ?",Math.max(1,Math.min(limit,200)),Math.max(0,offset));}
 @GetMapping("/activity") List<Map<String,Object>> activity(@RequestParam(defaultValue="0") int offset,@RequestParam(defaultValue="50") int limit){return db.queryForList("SELECT id,action,entity_type AS \"entityType\",entity_name AS \"entityName\",details,created_at AS \"createdAt\" FROM activity ORDER BY created_at DESC LIMIT ? OFFSET ?",Math.max(1,Math.min(limit,200)),Math.max(0,offset));}
 private void log(String action,String type,long id,String name,String details){db.update("INSERT INTO activity(action,entity_type,entity_id,entity_name,details) VALUES(?,?,?,?,?)",action,type,id,name,details);}
 private static String value(String s,String d,Set<String> allowed){String v=s==null||s.isBlank()?d:s;if(v==null||!allowed.contains(v))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid value: "+v);return v;}
 private static java.util.List<Object> append(java.util.List<Object> a,Object...v){a.addAll(java.util.Arrays.asList(v));return a;}
}
